import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import path from 'node:path';

export function createStore(filePath) {
  async function load() {
    try {
      return JSON.parse(await readFile(filePath, 'utf8'));
    } catch (err) {
      if (err.code === 'ENOENT') return [];
      throw err;
    }
  }

  async function save(books) {
    await mkdir(path.dirname(filePath), { recursive: true });
    // Write to a temp file then rename so a crash mid-write can't corrupt the data.
    const tmp = `${filePath}.tmp`;
    await writeFile(tmp, JSON.stringify(books, null, 2) + '\n', 'utf8');
    await rename(tmp, filePath);
  }

  return {
    async list() {
      return load();
    },

    async get(id) {
      const books = await load();
      return books.find((b) => b.id === id) ?? null;
    },

    async add({ title, author, notes = '' }) {
      const book = {
        id: randomUUID(),
        title,
        author,
        notes,
        status: 'reading',
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      const books = await load();
      books.push(book);
      await save(books);
      return book;
    },

    async markFinished(id) {
      const books = await load();
      const book = books.find((b) => b.id === id);
      if (!book) return null;
      if (book.status !== 'finished') {
        book.status = 'finished';
        book.finishedAt = new Date().toISOString();
        await save(books);
      }
      return book;
    },
  };
}

