import http from 'node:http';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createStore } from './lib/store.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_FILE = process.env.BOOKS_FILE ?? path.join(__dirname, 'data', 'books.json');
const PORT = Number(process.env.PORT ?? 3000);

const store = createStore(DATA_FILE);

function escapeHtml(s) {
  return String(s)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; color: #1a1a1a; line-height: 1.5; }
  h1 { font-size: 1.5rem; }
  h2 { font-size: 1.1rem; margin-top: 2rem; border-bottom: 1px solid #ddd; padding-bottom: 0.25rem; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { display: flex; align-items: baseline; gap: 0.5rem; padding: 0.4rem 0; }
  ul.books .author { color: #666; }
  ul.books form { margin-left: auto; }
  form.add { margin-top: 2rem; padding: 1rem; background: #f6f6f6; border-radius: 8px; }
  form.add label { display: block; margin-top: 0.75rem; font-weight: 600; }
  form.add input, form.add textarea { width: 100%; box-sizing: border-box; padding: 0.4rem; margin-top: 0.25rem; font: inherit; border: 1px solid #ccc; border-radius: 4px; }
  button { font: inherit; padding: 0.3rem 0.8rem; border: 1px solid #888; border-radius: 4px; background: #fff; cursor: pointer; }
  button:hover { background: #eee; }
  form.add button { margin-top: 1rem; background: #1a1a1a; color: #fff; border-color: #1a1a1a; }
  .notes { white-space: pre-wrap; background: #f6f6f6; padding: 1rem; border-radius: 8px; }
  .muted { color: #666; }
  a { color: #0b5cad; }
</style>
</head>
<body>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const finish =
    book.status === 'reading'
      ? `<form method="post" action="/books/${book.id}/finish"><button>Finished it</button></form>`
      : '';
  return `<li>
    <a href="/book/${book.id}">${escapeHtml(book.title)}</a>
    <span class="author">by ${escapeHtml(book.author)}</span>
    ${finish}
  </li>`;
}

async function homePage() {
  const books = await store.list();
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books.filter((b) => b.status === 'finished');
  const body = `
<h1>My books</h1>

<h2>Currently reading</h2>
${reading.length ? `<ul class="books">${reading.map(bookItem).join('\n')}</ul>` : '<p class="muted">Nothing right now.</p>'}

<h2>Finished</h2>
${finished.length ? `<ul class="books">${finished.map(bookItem).join('\n')}</ul>` : '<p class="muted">Nothing yet.</p>'}

<form class="add" method="post" action="/books">
  <strong>Add a book</strong>
  <label>Title <input name="title" required></label>
  <label>Author <input name="author" required></label>
  <label>Notes <textarea name="notes" rows="3"></textarea></label>
  <button>Add book</button>
</form>`;
  return page('My books', body);
}

function bookPage(book) {
  const status =
    book.status === 'finished'
      ? `Finished${book.finishedAt ? ` on ${book.finishedAt.slice(0, 10)}` : ''}`
      : 'Currently reading';
  const finish =
    book.status === 'reading'
      ? `<form method="post" action="/books/${book.id}/finish"><button>Mark as finished</button></form>`
      : '';
  const body = `
<p><a href="/">&larr; All books</a></p>
<h1>${escapeHtml(book.title)}</h1>
<p class="author">by ${escapeHtml(book.author)}</p>
<p class="muted">${status}</p>
${finish}
<h2>Notes</h2>
${book.notes ? `<div class="notes">${escapeHtml(book.notes)}</div>` : '<p class="muted">No notes.</p>'}`;
  return page(book.title, body);
}

function send(res, status, html) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

async function readForm(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 1e6) throw new Error('Request body too large');
  }
  return new URLSearchParams(body);
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);
    const bookMatch = url.pathname.match(/^\/book\/([\w-]+)$/);
    const finishMatch = url.pathname.match(/^\/books\/([\w-]+)\/finish$/);

    if (req.method === 'GET' && url.pathname === '/') {
      return send(res, 200, await homePage());
    }

    if (req.method === 'GET' && bookMatch) {
      const book = await store.get(bookMatch[1]);
      if (!book) return send(res, 404, page('Not found', '<h1>Book not found</h1><p><a href="/">&larr; All books</a></p>'));
      return send(res, 200, bookPage(book));
    }

    if (req.method === 'POST' && url.pathname === '/books') {
      const form = await readForm(req);
      const title = (form.get('title') ?? '').trim();
      const author = (form.get('author') ?? '').trim();
      const notes = (form.get('notes') ?? '').trim();
      if (!title || !author) {
        return send(res, 400, page('Missing fields', '<h1>Title and author are required</h1><p><a href="/">&larr; Back</a></p>'));
      }
      const book = await store.add({ title, author, notes });
      return redirect(res, `/book/${book.id}`);
    }

    if (req.method === 'POST' && finishMatch) {
      const book = await store.markFinished(finishMatch[1]);
      if (!book) return send(res, 404, page('Not found', '<h1>Book not found</h1><p><a href="/">&larr; All books</a></p>'));
      return redirect(res, '/');
    }

    send(res, 404, page('Not found', '<h1>Page not found</h1><p><a href="/">&larr; All books</a></p>'));
  } catch (err) {
    console.error(err);
    send(res, 500, page('Error', '<h1>Something went wrong</h1><p><a href="/">&larr; All books</a></p>'));
  }
});

server.listen(PORT, () => {
  console.log(`Book tracker running at http://localhost:${PORT}`);
});

