import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { createStore } from './store.mjs';

describe('book store', () => {
  let dir;
  let store;
  let file;

  beforeEach(async () => {
    dir = await mkdtemp(path.join(tmpdir(), 'books-'));
    file = path.join(dir, 'books.json');
    store = createStore(file);
  });

  afterEach(async () => {
    await rm(dir, { recursive: true, force: true });
  });

  it('starts empty when the file does not exist', async () => {
    expect(await store.list()).toEqual([]);
  });

  it('adds a book as currently reading', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'sandy' });
    expect(book.status).toBe('reading');
    expect(book.id).toBeTruthy();
    expect(await store.get(book.id)).toMatchObject({ title: 'Dune', author: 'Frank Herbert', notes: 'sandy' });
  });

  it('marks a book finished', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' });
    const finished = await store.markFinished(book.id);
    expect(finished.status).toBe('finished');
    expect(finished.finishedAt).toBeTruthy();
  });

  it('returns null when finishing an unknown id', async () => {
    expect(await store.markFinished('nope')).toBeNull();
  });

  it('persists to the JSON file across store instances', async () => {
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert' });
    const reopened = createStore(file);
    expect(await reopened.get(book.id)).toMatchObject({ title: 'Dune' });
    const raw = JSON.parse(await readFile(file, 'utf8'));
    expect(raw).toHaveLength(1);
  });
});

